          "type": "paragraph",
          "text": "Ofset baskı, baskı öncesi kalıp hazırlama (CtP), mürekkep ayarları ve makine hazırlık (makulasyon) süreçleri nedeniyle yüksek bir başlangıç kurulum maliyetine sahiptir. Ancak bir kez makine baskıya girdikten sonra, birim sayfa maliyeti son derece düşüktür. Dijital baskıda ise kalıp maliyeti yoktur ve hazırlık süresi sıfıra yakındır; ancak birim kopya (klik/toner) maliyeti sabittir. 2026 verilerine göre, standart bir 70x100 cm ticari broşür baskısında ofset ve dijital arasındaki maliyet eşitlenme (break-even) noktası 750 ila 1000 tabaka aralığındadır. Bu rakamın altındaki işler için dijital, üstündeki işler için ofset baskı kesinlikle daha ekonomiktir."
