          "type": "paragraph",
          "text": "Ofset baskı, geleneksel ıslak mürekkep transferi ve metal kalıplar sayesinde son derece keskin tram yapıları (amplitüd veya frekans modülasyonlu) ve mükemmel zemin doygunluğu sunar. Spektrofotometrik L-A-B renk yönetiminde, ofset baskı Delta E < 1.5 değerlerini en kararlı şekilde korur. Özellikle spot (Pantone) renklerin ve metalik yaldız mürekkeplerin basılmasında ofset teknolojisi tartışmasız liderdir. Dijital baskı ise sıvı elektro-mürekkep veya kuru toner teknolojisiyle 2400 dpi çözünürlüklere ulaşabilir; ancak büyük zemin alanlarda bazen dalgalanmalar gösterebilir ve gerçek metalik yaldız efekti vermekte sınırlıdır."
