          "text": "1. Водные краски: низкий уровень ЛОС (2-5%). Используются для гофрокартона и бумажных пакетов.\n2. Спиртовые (сольвентные) краски: отличная адгезия к пластиковым пленкам (PE, PP, PET) и высокий блеск.\n3. УФ-флексокраски: не содержат растворителей, отверждаются мгновенно под УФ-лампами. Идеальны для самоклеящихся этикеток."
