          "type": "paragraph",
          "text": "Düşük fiyatlı bir mürekkebin faturası genellikle başka kalemlerde ödenir: düşük pigment oranı daha kalın film ve daha yüksek tüketim; dengesiz tack yırtılma ve kâğıt tozu; zayıf kurutucu geç kuruma, set-off ve istif bekleme süresi; lot tutarsızlığı her siparişte yeniden ayar ve prova. Belgesiz bir ürün gıda ambalajı işinde müşteri denetiminden dönebilir. Bu kalemlerin her biri makine saatine ve kâğıda yazılır; bu yüzden teklif karşılaştırmasında TDS, lot tutarlılığı taahhüdü ve saha desteği de fiyatın parçası sayılmalıdır."
