          "text": "Цены на офсетные краски определяют восемь факторов: пигмент и сырьё, тип краски (конвенциональная, УФ, металлик, флуоресцентная), бренд и происхождение, упаковка и объём, формулирование цвета на заказ, регуляторные документы, логистика и валютный курс. Правильное сравнение — не цена за килограмм, а стоимость краски и брака на тысячу листов: краска с высоким содержанием пигмента дороже за килограмм, но дешевле в расчёте на тираж. Полная версия статьи доступна на английском и турецком языках; типы и бренды — в [руководстве по печатным краскам](/matbaa-murekkepleri)."
