          "text": "Metalik ve yaldız mürekkepler, ofset baskıda ek ünite veya kalıp olmadan altın ve gümüş efekt veren tek malzemedir; ancak doğru seçilmediğinde mat, kirli ya da sürtünmeyle dökülen bir sonuç üretirler. Seçim beş kararın toplamıdır: ton, pigment tipi, kâğıt, film kalınlığı ve kuruma–lak. Bu rehber PANTONE 871–877 ton tablosunu, kâğıt uyum tablosunu, sıcak yaldız folyoyla karşılaştırmayı ve sipariş öncesi kontrol listesini sunar. Ürünler için [EVA COLOR Gold](/urunler/eva-color-gold-metalik-murekkepler), [EVA COLOR Silver](/urunler/eva-color-silver-metalik-murekkepler) ve [SCHLENK metalik pigment ve mürekkepleri](/urunler/schlenk-metalik-murekkepler) sayfalarına, metalik grubun diğer türlerle ilişkisi için [matbaa mürekkepleri hub'ına](/matbaa-murekkepleri) bakın."
