          "type": "paragraph",
          "text": "Metalik parlaklık, bronz veya alüminyum plakacıkların mürekkep filmi içinde yatay dizilip ışığı aynasal yansıtmasından gelir. Bu fiziksel gerçek seçimin tüm kurallarını üretir: plakacıkların düzgün yatması için pürüzsüz, kaplı bir yüzey (parlak kuşe) gerekir; yeterli sayıda plakacık için film kalınlığı standart CMYK'dan yüksek olmalıdır; plakacıklar yüzeyde olduğu için sürtünme direnci düşer ve koruyucu lak gerekir; plakacık boyutu büyüdükçe parlaklık artar ama ince tramda baskı kalitesi düşer. Parlaklık, renk değeri L* ile değil 60° gloss ölçümüyle (GU) değerlendirilir; parlak kuşede kaliteli bir metalik ofset mürekkebi 85–95 GU verir."
