          "text": "Tasarım dosyasında PANTONE metalik kodu ve kâğıt tipi yazılı mı? Kâğıt parlak kuşe mi; değilse primer veya yüksek pigmentli seri planlandı mı? Metalik üstüne baskı var mı (non-leafing ve yapışma testi)? Lak uygulanacak mı; lak numunesi görüldü mü? Baskı sistemi konvansiyonel mi UV mi (seri buna göre)? Gıda teması varsa düşük migrasyonlu seri ve belge istendi mi? Gümüş için ayrı ekipman ayrıldı mı? Numune ve TDS alındı mı? Bu sorulara verilen cevaplar, teklifin doğru seriyi ve doğru ambalajı içermesini sağlar; SIM, EVA COLOR metalik serilerini numune ve makine başında deneme baskısıyla sunar, özel altın ve gümüş tonlarını laboratuvarda formüle eder. Tüm ürün gruplarının bütünü için [matbaa malzemeleri rehberine](/matbaa-malzemeleri) bakın."
