          "text": "Yatırım tarafında LED üniteleri klasik UV ünitelerinden pahalıdır; retrofit (mevcut makineye LED kürleme ekleme) maliyeti makine tipine göre değişir. İşletme tarafında LED; enerji, lamba değişimi, havalandırma ve stand-by kayıplarında tasarruf sağlar, mürekkep ise daha pahalıdır. İş başına maliyette belirleyici, mürekkep fiyat farkının enerji ve lamba tasarrufuyla dengelenip dengelenmediğidir: yüksek enerji maliyeti, çok sayıda kısa iş (sık açılış–kapanış) ve ısıya duyarlı malzeme payı yüksek matbaalarda LED hızlı geri döner; uzun tirajlı, yoğun opak ve kalın film işleri ağırlıklı hatlarda klasik UV hâlâ rekabetçidir. Aşağıdaki tablo kalemleri karşılaştırır; rakamlar makine, tiraj ve enerji fiyatına göre teklifte netleşir."
