          "type": "paragraph",
          "text": "Baskıdaki her kusur blanketten kaynaklanmaz, ama birkaç kusurun ilk kontrol noktası blankettir. Kayma (slur) ve çift baskı (doubling) çoğunlukla gevşek gerdirme veya yanlış altlık yüksekliğinin sonucudur. Hayalet görüntü (ghosting) blanketin önceki işten mürekkep veya pas izi taşımasıyla ortaya çıkar. Aşırı nokta kazancı, fazla baskı basıncına veya sert yüzeyli konvansiyonel blankete işaret eder; kazancın ölçümü ve referans değerleri için [dot gain kontrolü](/blog/baskida-dot-gain-kontrolu) yazısına bakabilirsiniz. Çizgi ve şerit izleri genellikle dişli iziyle (gear streak) karıştırılır, oysa blanket yüzeyindeki yerel aşınma da aynı görünümü verir. Yüzeyde yolma (picking) ve kâğıt tozu birikmesi (piling) blanketin yapışkanlığı artan, 'camlaşmış' yüzeyiyle ilgilidir ve çözümü uygun yıkama ile yüzey yenilemedir. Ezilme (smash) ise kâğıt katlanması veya yabancı cisimden kaynaklanan yerel çökmedir; küçük çökmeler blanket onarım pastasıyla geçici olarak kaldırılabilir, büyükleri değişim gerektirir. Aşağıdaki tablo bu sorunların blanket tarafındaki kontrol noktalarını özetler."
