          "type": "paragraph",
          "text": "Blanket satın almada en yaygın hata adet fiyatına bakmaktır. Gerçek maliyet üç kalemden oluşur: blanket bedeli ÷ ömrü boyunca basılan tabaka sayısı, her değişimde kaybedilen makine süresi (duruş maliyeti × değişim süresi) ve blanket kaynaklı fire. Bu hesapla yüzde yirmi daha pahalı ama yüzde kırk daha uzun ömürlü bir blanket, ucuz blanketten belirgin şekilde ekonomik çıkar; üstelik daha az değişim daha az kayıt ve renk ayarı demektir. Hesabın güvenilir olması için her ünitede blanket günlüğü tutulmalıdır: takılma tarihi, lot, basılan tabaka, değişim nedeni (aşınma, ezilme, kalite düşüşü). Birkaç ay sonra bu günlük hangi blanketin hangi iş karmasında daha uzun gittiğini ve hangi ünitenin daha çok ezilme yaşadığını (kâğıt besleme sorununa işaret eder) net gösterir. Fire tarafındaki ilişkiyi [fire oranını düşürme](/blog/ofset-baskida-fire-oranini-dusurme) yazısında ayrıntılı ele aldık; blanket değişim planını kâğıt ve mürekkep siparişiyle birlikte düşünen matbaalar toplam malzeme maliyetini en iyi kontrol eder. Konvansiyonel [SAKATA INX CMYK](/urunler/sakata-inx-cmyk-murekkepler) gibi hızlı kuruyan serilerle çalışan ünitelerde blanket yüzeyinin daha az kimyasala maruz kalması da ömrü uzatan bir etkendir."
