          "text": "İzopropil alkol yüzey gerilimini düşürüp nemlendirme suyunu kalıp üzerinde ince ve eşit yaydığı için uzun yıllar standart katkı oldu; geleneksel oran %8–12'dir. Ancak IPA uçucu organik bileşik (VOC) sayılır, yangın riski taşır ve işçi sağlığı açısından sınırlamalara tabidir; AB'de 2010/75/EU Endüstriyel Emisyonlar Direktifi, Türkiye'de ise KKDİK ve iş sağlığı mevzuatı bu kullanımı baskılar. Bu nedenle üreticiler alkol azaltılmış (%3–5 IPA) ve alkolsüz (%0) çalışmaya uygun katkılar geliştirdi. Alkolsüz sisteme geçiş, nemlendirme ünitesinin (merdane kaplaması, soğutma, filtreleme) uygun olmasını ve katkının bu moda göre seçilmesini gerektirir; aksi hâlde su-mürekkep dengesi daralır ve operatörün tolerans aralığı küçülür. Karar makineye göre verilir: modern soğutmalı sürekli nemlendirme sistemleri alkolsüz çalışmaya uygundur, eski sistemlerde alkol azaltılmış kademe daha güvenli bir geçiştir."
