          "type": "paragraph",
          "text": "Yıkama solventi seçiminde ilk kriter parlama noktasıdır. Parlama noktası 55 °C ve üzeri olan 'yüksek parlama noktalı' yıkamalar hem depolama ve taşıma sınıfı hem de VOC açısından daha güvenlidir; 21 °C altı ürünler hızlı kurur ama yangın ve buhar riski taşır. İkinci kriter kauçuk uyumudur: agresif solventler blanket yüzeyini şişirir ve merdane kaplamasını sertleştirir; bu yüzden solventin [VECTOR baskı blanketleri](/urunler/vector-baski-blanketleri) gibi kullandığınız blanket ve merdane malzemesiyle uyumlu olduğunu TDS'de kontrol edin. Üçüncü kriter kuruma ve geri bulaşma süresidir: otomatik yıkama sistemlerinde çok yavaş kuruyan solvent bir sonraki tabakaya iz bırakır. UV mürekkep basıyorsanız konvansiyonel yıkama yetmez; [Zeller+Gmelin UV ofset mürekkepleri](/urunler/zeller-gmelin-uv-offset-murekkepleri) için UV uyumlu yıkama ve blanket gerekir. Blanket ömrünü uzatan temizlik ve bakım rutinini [blanket seçimi ve bakımı](/blog/baski-blanket-secimi-ve-bakimi) yazısında anlattık."
