          "type": "paragraph",
          "text": "Kimyasalda litre veya kilogram fiyatı yanıltıcıdır çünkü tüketim dozaja bağlıdır. Doğru karşılaştırma birimi bin tabaka (veya bin baskı) başına kimyasal maliyetidir: hazne suyu için (dozaj yüzdesi × saatlik su tüketimi × litre fiyatı) ÷ saatlik tabaka sayısı; yıkama için (yıkama başına solvent miktarı × vardiya başına yıkama sayısı × litre fiyatı) ÷ vardiya tabaka sayısı. %3 dozajla çalışan daha pahalı bir katkı, %4 gerektiren ucuz katkıdan iş başına daha ekonomik çıkabilir; parlama noktası yüksek bir solvent daha yavaş uçtuğu için daha az tüketilir. Hesaba IPA tüketimini, fire oranını ve blanket değişim sıklığını da eklediğinizde kimyasalın gerçek maliyeti ortaya çıkar. Fire tarafındaki kazanım için [ofset baskıda fire oranını düşürme](/blog/ofset-baskida-fire-oranini-dusurme) yazısındaki yöntemler kimyasal maliyetiyle birlikte değerlendirilmelidir."
