          "type": "paragraph",
          "text": "SIM Baskı Malzemeleri 1983'ten bu yana ofset mürekkep, blanket ve baskı kimyasallarını tek çatı altında tedarik eder; kimyasalı mürekkep ve blanketle birlikte seçmek uyumsuzluk kaynaklı sorunların büyük bölümünü baştan önler. Hazne suyu katkısı, IPA ve alkol ikameleri, yıkama solventleri, kalıp kimyasalları ve yardımcı sarflar stoktan sevk edilir: İstanbul içinde saat 12:00'a kadar verilen siparişler aynı gün, Türkiye geneli 1–2 iş günü içinde teslim edilir. Su analizi, dozaj ayarı ve alkolsüz sisteme geçiş gibi konularda teknik ekibimiz sahada ve uzaktan destek verir. Kullandığınız makine, kâğıt ve mürekkep bilgisiyle [bize ulaşın](/iletisim); size uygun kimyasal setini ve bin tabaka maliyet karşılaştırmasını birlikte çıkaralım."
