          "type": "intro",
          "text": "Печатная химия делится на пять групп: добавка в увлажняющий раствор, изопропиловый спирт (IPA) или его заменители, смывки для офсетных полотен и валиков, химия для форм и вспомогательные материалы (противоотмарочный порошок, сиккативы, лаки). Выбор начинается с анализа воды: жёсткость 8–12 °dH, проводимость сырой воды ниже 300 мкСм/см, pH раствора 4,8–5,5. Смывки выбирают по температуре вспышки (выше 55 °C) и совместимости с резиной полотен и валиков; для УФ-красок нужны специальные смывки."
