          "type": "paragraph",
          "text": "Сравнивайте не цену за литр, а стоимость химии на тысячу листов: дозировка × расход × цена. Для каждого продукта запрашивайте технический лист (TDS) и паспорт безопасности (SDS), проверяйте содержание ЛОС, срок хранения (обычно 12 месяцев при 5–30 °C) и номер партии. SIM поставляет печатную химию, краски и полотна из Стамбула с 1983 года, включая экспорт на Ближний Восток, в Центральную Азию и на Балканы; полная версия статьи доступна на турецком и английском языках."
