          "type": "intro",
          "text": "Balkanlar'dan Körfez'e, Orta Asya'dan Kuzey Afrika'ya kadar pek çok matbaa ofset mürekkebini, blanketini ve baskı kimyasalını Türkiye'den tedarik ediyor; sebebi coğrafi yakınlık, AB ile Gümrük Birliği, Avrupa standartlarında üretim ve rekabetçi toplam maliyet. Ancak ilk ihracat siparişinde alıcı tarafın en çok takıldığı konular ürünün kendisi değil süreçtir: hangi Incoterm seçilmeli, hangi belgeler gelir, renk uzaktan nasıl eşleştirilir, ödeme nasıl yapılır, mal ne zaman çıkar? Bu yazı SIM Baskı Malzemeleri'nin yurt dışı müşterileriyle uyguladığı yedi adımlı süreci, belge ve Incoterm tablolarıyla anlatır. Ürün yelpazesi ve teklif formu için [ihracat sayfamıza](/ihracat), mürekkep odaklı tedarik için [ofset mürekkep ihracatı](/ofset-murekkep-ihracati) sayfasına bakabilirsiniz."
